bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
root=/home/gace/.local/share/gace-create-videobot/native-sticker-c8c50d420c0b9b5d447a1fc87ef3d9e1ec7aceed
stage="$root/.releases/5aff60b6371f422120398212-album-id-stage"
old=create-videobot:before-album-id-5aff60b6
new=create-videobot:album-id-5aff60b6-tested
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
test -f "$root/deploy/compose.videobot.poll.yaml" || exit 63
test ! -e "$stage" && test -z "$(docker images -q "$new")" || exit 64
mkdir -p "$stage/src/telegram" "$stage/test"
docker cp "$cid:/opt/videobot/src/telegram/paidListingPublisher.mjs" "$stage/src/telegram/paidListingPublisher.mjs" || exit 65
export GACE_ALBUM_STAGE="$stage"
python3 -B - <<'PY'
from pathlib import Path
import os
p=Path(os.environ['GACE_ALBUM_STAGE'])/'src/telegram/paidListingPublisher.mjs'
s=p.read_text()
old="""      if (!Array.isArray(preview) || preview.length !== 2 ||
          preview.some(m=>!Number.isSafeInteger(m?.message_id)||m.message_id<=0))
        throw new Error('free album acknowledgment invalid');"""
new="""      if (!Array.isArray(preview) || preview.length !== 2 ||
          preview.some(m=>!Number.isSafeInteger(m?.message_id)||m.message_id<=0) ||
          preview[0].message_id === preview[1].message_id ||
          typeof preview[0].media_group_id !== 'string' ||
          !preview[0].media_group_id ||
          preview[0].media_group_id !== preview[1].media_group_id)
        throw new Error('free album acknowledgment invalid: media_group_id mismatch');"""
if s.count(old)!=1:raise SystemExit(66)
p.write_text(s.replace(old,new))
PY
cat > "$stage/test/album-readback.test.mjs" <<'JS'
import test from 'node:test';
import assert from 'node:assert/strict';
import {publishVideoListing} from '../src/telegram/paidListingPublisher.mjs';
const listing={id:'album_check',sellerId:'123456',revision:1,title:'album test',priceStars:10,
  thumbnail:{fileId:'photo001'},sample:{fileId:'sample001'},paidVideo:{fileId:'video001'},
  rightsVerified:true,adultConsentVerified:true,ownerConfirmedPublish:true,
  feeTermsAccepted:true,managementFeeBps:3000};
function ports(bad=false){
 let row=null;const calls=[];
 const store={
  async claim(){if(row)return {claimed:false};row={status:'sending',freeMessageIds:null};return {claimed:true};},
  async read(){return row;},
  async recordFree(key,ids){row.freeMessageIds=ids;},
  async recordPaid(key,id){row.paidMessageId=id;row.status='sent';},
  async markUnknown(){row.status='needs_reconcile';}
 };
 return {listing,store,calls,getVerifiedVideoTopic:async()=>({id:4650,chatId:-1002373696859,threadId:4650,board:'video_chat',purpose:'video_sale',enabled:true,verified:true,title:'paid video'}),
  telegramApi:async(method,params)=>{calls.push(method);if(method==='sendMediaGroup'){
    assert.equal(params.media.length,2);assert.deepEqual(params.media.map(x=>x.has_spoiler),[true,true]);
    return [{message_id:100,media_group_id:'album_100'},
      {message_id:101,media_group_id:bad?'album_OTHER':'album_100'}];
  }assert.equal(method,'sendPaidMedia');assert.equal(params.star_count,10);return {message_id:102};}};
}
test('shared native album id and Stars post complete once',async()=>{
 const p=ports();const result=await publishVideoListing(p);
 assert.equal(result.paidMessageId,102);
 assert.deepEqual(p.calls,['sendMediaGroup','sendPaidMedia']);
 assert.equal((await publishVideoListing(p)).alreadySent,true);
 assert.equal(p.calls.length,2);
});
test('broken native album readback locks receipt without paid send or replay',async()=>{
 const p=ports(true);
 await assert.rejects(()=>publishVideoListing(p),/media_group_id mismatch/);
 assert.deepEqual(p.calls,['sendMediaGroup']);
 assert.equal((await p.store.read()).status,'needs_reconcile');
 await assert.rejects(()=>publishVideoListing(p),/PUBLISH_NEEDS_RECONCILE/);
 assert.equal(p.calls.length,1);
});
JS
cat > "$stage/Dockerfile" <<'EOF'
FROM create-videobot:before-album-id-5aff60b6
USER root
COPY --chown=node:node src/telegram/paidListingPublisher.mjs /opt/videobot/src/telegram/paidListingPublisher.mjs
COPY --chown=node:node test/album-readback.test.mjs /opt/videobot/test/album-readback.test.mjs
USER node
EOF
docker tag "$(docker inspect "$cid" --format '{{.Image}}')" "$old" || exit 67
docker build --network none --pull=false -t "$new" "$stage" >/dev/null || exit 68
docker run --rm --network none --entrypoint node "$new" --check /opt/videobot/src/telegram/paidListingPublisher.mjs || exit 69
docker run --rm --network none -w /opt/videobot --entrypoint node "$new" --test test/album-readback.test.mjs > "$stage/test-results.log" 2>&1 || exit 70
grep -q 'pass 2' "$stage/test-results.log" || exit 71
grep -q 'fail 0' "$stage/test-results.log" || exit 72
echo VIDEO_ALBUM_ID_STAGE=PASS
echo VIDEO_ALBUM_ID_TESTS=PASS
